    N.proof_n = s:text { x = 64, y = 60, text = "06", size = 26, font = MONO, color = TEAL, opacity = 0 }
    N.proof_t = s:text { x = 64, y = 94, text = "And checks its own work", size = 46, font = BOLD, color = INK, opacity = 0 }
    N.cl_t = s:text { x = 960, y = 468, text = "Cadence", size = 120, font = BOLD, color = INK, anchor = "center", opacity = 0 }
    N.cl_s = s:text { x = 960, y = 574, text = "real pixels, measured into words, edited by assertion", size = 32, font = SANS, color = INK, anchor = "center", opacity = 0 }
    s:rect { x = 0, y = 930, w = 1920, h = 150, color = "#000000b3" }
    s:captions { x = 960, y = 978, size = 38, font = SANS, color = INK, anchor = "center", cues = {
      { 0.700, 2.580, "This is a real clip." },
      { 2.580, 4.895, "Fourteen seconds, nothing added." },
      { 4.895, 6.412, "Everything you are about to see drawn" },
      { 6.412, 7.655, "on top of it was measured from" },
      { 7.655, 9.969, "these pixels and written down as facts." },
      { 10.900, 13.490, "A detector proposes a box," },
      { 13.490, 16.525, "and SAM two propagates the mask forwards" },
      { 16.525, 18.480, "and backwards from that seed." },
      { 18.480, 20.510, "Two entities survive here:" },
      { 20.510, 22.715, "a bottle, and a gloved hand." },
      { 22.715, 25.250, "These boxes are the tracker's own output." },
      { 25.250, 27.175, "The loose one is exactly why every" },
      { 27.175, 29.760, "fact carries a confidence instead of pretending" },
      { 29.760, 30.889, "to be exact." },
      { 32.000, 33.120, "Here is the translation." },
      { 33.120, 34.935, "A box is a rectangle of numbers," },
      { 34.935, 37.435, "and the log refuses to store numbers." },
      { 37.435, 39.465, "It stores the word an editor would" },
      { 39.465, 40.785, "say out loud." },
      { 40.785, 42.085, "While the bottle sits in the middle" },
      { 42.085, 44.070, "third, the log says so," },
      { 44.070, 46.200, "and records the interval it held for." },
      { 47.330, 49.635, "Movement gets the same treatment." },
      { 49.635, 50.935, "Not pixels per second," },
      { 50.935, 52.945, "but a direction and an adverb." },
      { 52.945, 54.780, "Moving left, fast," },
      { 54.780, 56.690, "from seven point nine seconds to ten" },
      { 56.690, 57.559, "point four." },
      { 58.850, 60.230, "Then the moment." },
      { 60.230, 62.315, "The gap between the two masks opens" },
      { 62.315, 63.990, "at eight and a half seconds," },
      { 63.990, 65.550, "and that becomes an event," },
      { 65.550, 67.535, "carrying the producer that measured it and" },
      { 67.535, 69.080, "how sure it was." },
      { 69.080, 70.775, "Nothing in this log claims to be" },
      { 70.775, 73.210, "exact, because nothing in it is." },
      { 74.480, 76.275, "Now the agent works." },
      { 76.275, 77.665, "It never looks at the picture." },
      { 77.665, 79.115, "It asks the log when the bottle" },
      { 79.115, 81.345, "changed hands, gets eight point five," },
      { 81.345, 83.629, "and asserts that the caption belongs there." },
      { 84.580, 86.822, "Then it proves what it did." },
      { 86.822, 89.730, "Render both versions and hash every frame." },
      { 89.730, 91.345, "One hundred of three hundred and fifty" },
      { 91.345, 93.765, "eight differ, in exactly two windows:" },
      { 93.765, 95.280, "where the caption used to be," },
      { 95.280, 96.550, "and where it is now." },
      { 96.550, 97.979, "Nothing else moved." },
      { 99.405, 102.730, "Real pixels, measured into words," },
      { 102.730, 104.238, "edited by assertion." },
    } }
